package runtime
import("context";"testing";"time";provider "github.com/DesKaOne/DesKaEcosystem/DesKaProvider/Provider";mock "github.com/DesKaOne/DesKaEcosystem/DesKaProvider/Provider/Mock";"github.com/DesKaOne/DesKaEcosystem/DesKaProvider/Provider/operational";"github.com/DesKaOne/DesKaEcosystem/DesKaProvider/catalog";"github.com/DesKaOne/DesKaEcosystem/DesKaProvider/routing")
func TestProviderRouteExplanationIsInternalAndReadinessNeutral(t *testing.T){r:=provider.NewRegistry();if err:=r.RegisterWithCapabilities("mock",mock.New(mock.Config{Products:[]provider.Product{{Code:"xld10"}}}),provider.CapabilityDescriptor{Capabilities:map[provider.Capability]provider.CapabilityStatus{provider.CapabilityPPOB:{AdapterImplemented:true,Enabled:true}}});err!=nil{t.Fatal(err)};states:=operational.NewProviderStateStore();d,_:=r.Capabilities("mock");if err:=states.Put(operational.ProviderState{ProviderName:"mock",Lifecycle:operational.LifecycleEnabled,Capabilities:[]operational.Capability{operational.CapabilityPPOB},CapabilityFingerprint:operational.CapabilityMetadataFingerprint(d)});err!=nil{t.Fatal(err)};store:=operational.NewMemoryStore();if err:=store.Put(operational.Snapshot{ProviderName:"mock",Balance:1000,Currency:"IDR",Health:operational.HealthHealthy,LastCheckedAt:time.Now()});err!=nil{t.Fatal(err)};cat:=catalog.NewMemoryStore();if err:=cat.Put(catalog.Snapshot{ProviderName:"mock",Products:[]provider.Product{{Code:"xld10"}},SyncedAt:time.Now()});err!=nil{t.Fatal(err)};router,err:=routing.NewWithCatalogAndStateAndOperationalMaxAge(r,store,nil,cat,states,time.Hour);if err!=nil{t.Fatal(err)};svc:=&Service{providerState:states};svc.purchaseService,err=routing.NewService(router);if err!=nil{t.Fatal(err)};e,err:=svc.ExplainProviderRoute(context.Background(),"mock",provider.CapabilityPPOB,"xld10",100);if err!=nil{t.Fatal(err)};if !e.RouteEligible{t.Fatalf("unexpected ineligible route: %#v",e)}}
